      "title": "My routine",
      "description": "Wake me up at 6 am",
      "tag": "personal",
      "date": "2025-07-30T10:17:13.493Z",
      "__v": 0
    }]

    const [notes,setNotes] = useState(notesInitial)
  return (
    <NoteContext.Provider value={{notes, setNotes}}>
      {props.children}
    </NoteContext.Provider>
  );
};

export default NoteState;
